rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /phase3-language/string-trim {
      allow get: if '  Fireside  '.trim() == 'Fireside';
    }
    match /phase3-language/string-case {
      allow get: if 'FiRe'.lower() == 'fire' && 'FiRe'.upper() == 'FIRE';
    }
    match /phase3-language/string-replace {
      allow get: if 'abcabc'.replace('a', 'x') == 'xbcxbc';
    }
    match /phase3-language/string-split {
      allow get: if 'a,b,c'.split(',') == ['a', 'b', 'c'];
    }
    match /phase3-language/string-match {
      allow get: if 'phase3'.matches('^phase[0-9]$');
    }
    match /phase3-language/string-coercion {
      allow get: if string(123) == '123' && string(true) == 'true';
    }
    match /phase3-language/list-concat {
      allow get: if [1, 2].concat([3]) == [1, 2, 3];
    }
    match /phase3-language/list-membership {
      allow get: if [1, 2, 3].hasAll([1, 3]) && [1, 2, 3].hasAny([9, 2]);
    }
    match /phase3-language/list-has-only {
      allow get: if [1, 2, 2].hasOnly([2, 1]);
    }
    match /phase3-language/list-join {
      allow get: if ['a', 'b', 'c'].join('-') == 'a-b-c';
    }
    match /phase3-language/list-remove-all {
      allow get: if [1, 2, 3, 2].removeAll([2]) == [1, 3];
    }
    match /phase3-language/list-index-range {
      allow get: if [10, 20, 30][1] == 20 && [10, 20, 30][0:2] == [10, 20];
    }
    match /phase3-language/map-get {
      allow get: if {'a': 1}.get('missing', 7) == 7 && {'a': 1}.get('a', 7) == 1;
    }
    match /phase3-language/map-keys-values {
      allow get: if {'a': 1, 'b': 2}.keys().hasOnly(['a', 'b']) && {'a': 1, 'b': 2}.values().hasAll([1, 2]);
    }
    match /phase3-language/map-size-membership {
      allow get: if {'a': 1, 'b': 2}.size() == 2 && 'a' in {'a': 1};
    }
    match /phase3-language/map-diff {
      allow get: if {'a': 1, 'b': 2}.diff({'a': 1, 'b': 3, 'c': 4}).affectedKeys().hasOnly(['b', 'c']);
    }
    match /phase3-language/map-diff-sets {
      allow get: if {'a': 1, 'b': 2}.diff({'a': 1, 'b': 3, 'c': 4}).changedKeys().hasOnly(['b']) && {'a': 1, 'b': 2}.diff({'a': 1, 'b': 3, 'c': 4}).addedKeys().hasOnly(['c']);
    }
    match /phase3-language/set-union {
      allow get: if ['a', 'b'].toSet().union(['b', 'c'].toSet()).hasOnly(['a', 'b', 'c']);
    }
    match /phase3-language/set-intersection {
      allow get: if ['a', 'b'].toSet().intersection(['b', 'c'].toSet()).hasOnly(['b']);
    }
    match /phase3-language/set-difference {
      allow get: if ['a', 'b'].toSet().difference(['b'].toSet()).hasOnly(['a']);
    }
    match /phase3-language/bytes-size-hex {
      allow get: if 'abc'.toUtf8().size() == 3 && 'abc'.toUtf8().toHexString() == '616263';
    }
    match /phase3-language/bytes-base64-unicode {
      allow get: if 'é'.toUtf8().size() == 2 && 'abc'.toUtf8().toBase64() == 'YWJj';
    }
    match /phase3-language/duration-seconds {
      allow get: if duration.value(90, 's').seconds() == 90;
    }
    match /phase3-language/duration-nanos {
      allow get: if duration.value(123, 'ns').nanos() == 123;
    }
    match /phase3-language/timestamp-date {
      allow get: if timestamp.date(2024, 2, 29).year() == 2024 && timestamp.date(2024, 2, 29).month() == 2;
    }
    match /phase3-language/timestamp-components {
      allow get: if timestamp.date(2024, 2, 29).day() == 29 && timestamp.date(2024, 2, 29).dayOfWeek() == 4;
    }
    match /phase3-language/timestamp-arithmetic {
      allow get: if timestamp.date(2024, 2, 29) + duration.value(1, 'd') == timestamp.date(2024, 3, 1);
    }
    match /phase3-language/latlng-components {
      allow get: if latlng.value(1.25, 2.5).latitude() == 1.25 && latlng.value(1.25, 2.5).longitude() == 2.5;
    }
    match /phase3-language/latlng-distance {
      allow get: if latlng.value(1, 2).distance(latlng.value(1, 2)) == 0.0;
    }
    match /phase3-language/math-basic {
      allow get: if math.abs(-2) == 2 && math.ceil(1.2) == 2 && math.floor(1.8) == 1;
    }
    match /phase3-language/math-round-sqrt {
      allow get: if math.round(1.6) == 2 && math.sqrt(81) == 9;
    }
    match /phase3-language/math-pow {
      allow get: if math.pow(2, 3) == 8;
    }
    match /phase3-language/hashing-md5 {
      allow get: if hashing.md5('abc'.toUtf8()).toHexString() == '900150983CD24FB0D6963F7D28E17F72';
    }
    match /phase3-language/hashing-sha256 {
      allow get: if hashing.sha256('abc'.toUtf8()).toHexString() == 'BA7816BF8F01CFEA414140DE5DAE2223B00361A396177A9CB410FF61F20015AD';
    }
    match /phase3-language/debug-return {
      allow get: if debug(request.auth.uid) == 'phase3-user';
    }
    match /phase3-language/request-auth {
      allow get: if request.auth.uid == 'phase3-user' && request.auth.token.role == 'editor';
    }
    match /phase3-language/request-method-time {
      allow get: if request.method == 'get' && request.time.year() == 2026;
    }
    match /phase3-language/path-value {
      allow get: if resource.__name__ == /databases/$(database)/documents/phase3-language/path-value;
    }
    function usesLet(input) {
      let doubled = input * 2;
      let shifted = doubled + 1;
      return shifted == 7;
    }
    match /phase3-language/function-let {
      allow get: if usesLet(3);
    }
    match /phase3-language/resource-update-diff {
      allow update: if resource.data.name == 'before' && request.resource.data.name == 'after' && request.resource.data.diff(resource.data).affectedKeys().hasOnly(['name']);
    }
    match /phase3-language/query-limit {
      allow list: if request.query.limit == 10;
    }
    match /phase3-language/nested-match {
      match /child/{childId} {
        allow get: if childId == 'doc';
      }
    }
    match /phase3-language/recursive-match/{tail=**} {
      allow get: if tail == /a/b/c;
    }
    match /phase3-language/overlapping-allow {
      allow get: if false;
      allow read: if true;
    }
  }
}

cases.customMatch:
function usesLet(input) {
  let doubled = input * 2;
  let shifted = doubled + 1;
  return shifted == 7;
}
match /phase3-language/function-let {
  allow get: if usesLet(3);
}

match /phase3-language/nested-match {
  match /child/{childId} {
    allow get: if childId == 'doc';
  }
}

match /phase3-language/overlapping-allow {
  allow get: if false;
  allow read: if true;
}
